def F(s, n):
    if s <= 1:
        return n % 2 == 0
    if n == 0:
        return 0
    h = [F(s - 1, n - 1)]
    if s >= 4:
        h += [F(s - 4, n - 1)]
    if s % 3 == 0:
        h += [F(s / 3, n - 1)]
    return any(h) if (n - 1) % 2 == 0 else all(h)

print([s for s in range(4, 100 + 1) if F(s, 2)])
print([s for s in range(4, 100 + 1) if F(s, 3) and not F(s, 1)])
print([s for s in range(4, 100 + 1) if F(s, 4) and not F(s, 2)])
